<script setup lang="ts">
import { Plus, Save, Trash2, Wrench } from 'lucide-vue-next';
import { onMounted, ref } from 'vue';

type Tool = { id: string; type: 'shell'|'mcp'|'rest'; name: string; description: string; enabled: boolean; builtin?: boolean; config: Record<string, any> };
const tools = ref<Tool[]>([]); const selected = ref<Tool | null>(null); const bodyText = ref('{}'); const error = ref(''); const message = ref(''); const testing = ref(false);
const blank = (): Tool => ({ id: '', type: 'shell', name: '', description: '', enabled: true, config: { command: '', timeoutSeconds: 30 } });
async function load() { const r = await fetch('/api/tools'); const d = await r.json(); if (d.success) tools.value = d.tools; else error.value = d.error || 'Failed to load tools'; }
function add() { selected.value = blank(); message.value = ''; error.value = ''; }
function edit(t: Tool) { selected.value = JSON.parse(JSON.stringify(t)); bodyText.value = JSON.stringify(selected.value?.config?.body || {}, null, 2); message.value = ''; error.value = ''; }
async function save() { if (!selected.value?.name) return; if (selected.value.type === 'rest') { try { selected.value.config.body = JSON.parse(bodyText.value || '{}'); } catch { error.value = 'REST body must be valid JSON'; return; } } const method = selected.value.id ? 'PUT' : 'POST'; const url = selected.value.id ? `/api/tools/${selected.value.id}` : '/api/tools'; const r = await fetch(url, { method, headers: {'Content-Type':'application/json'}, body: JSON.stringify(selected.value) }); const d = await r.json(); if (!d.success) { error.value = d.detail || d.error || 'Save failed'; return; } message.value = 'Tool saved'; selected.value = null; await load(); }
async function toggle(t: Tool) { await fetch(`/api/tools/${t.id}/${t.enabled ? 'disable' : 'enable'}`, { method: 'POST' }); await load(); }
async function remove(t: Tool) { if (t.builtin || !confirm(`Remove ${t.name}?`)) return; await fetch(`/api/tools/${t.id}`, { method: 'DELETE' }); if (selected.value?.id === t.id) selected.value = null; await load(); }
async function test() { if (!selected.value?.id) return; testing.value = true; const r = await fetch(`/api/tools/${selected.value.id}/test`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ filename: 'project.zip' }) }); const d = await r.json(); message.value = d.success ? 'Test succeeded' : (d.result?.error || 'Test failed'); testing.value = false; }
function updateType() { if (!selected.value) return; selected.value.config = selected.value.type === 'shell' ? { command: '', timeoutSeconds: 30 } : selected.value.type === 'mcp' ? { command: '', args: [], timeoutSeconds: 30 } : { method: 'GET', url: '', allowedHosts: [], timeoutSeconds: 30, body: {} }; bodyText.value = '{}'; }
onMounted(load);
</script>

<template>
  <section class="rounded-2xl border border-slate-800 bg-slate-900/40 p-5 space-y-4">
    <div class="flex items-center justify-between"><div><h3 class="text-lg font-bold text-white flex items-center gap-2"><Wrench class="w-5 h-5 text-cyan-400" /> LLM Tools</h3><p class="text-xs text-slate-400 mt-1">Manage shell, MCP, and REST tools exposed to the orchestrator.</p></div><button class="px-3 py-2 rounded-lg bg-indigo-600 text-white text-xs font-semibold" @click="add"><Plus class="w-3.5 h-3.5 inline mr-1" />Add tool</button></div>
    <p v-if="error" class="text-xs text-rose-300">{{ error }}</p><p v-if="message" class="text-xs text-emerald-300">{{ message }}</p>
    <div class="grid gap-2"><div v-for="tool in tools" :key="tool.id" class="flex items-center justify-between rounded-xl border border-slate-800 bg-slate-950/30 p-3"><button class="text-left min-w-0" @click="edit(tool)"><div class="text-sm text-white font-semibold truncate">{{ tool.name }} <span class="text-[10px] uppercase text-cyan-300 ml-2">{{ tool.type }}</span></div><div class="text-xs text-slate-500 truncate">{{ tool.description || 'No description' }}</div></button><div class="flex items-center gap-2"><button v-if="!tool.builtin" class="text-[11px] text-slate-400" @click="toggle(tool)">{{ tool.enabled ? 'Disable' : 'Enable' }}</button><button v-if="!tool.builtin" class="text-rose-300" @click="remove(tool)"><Trash2 class="w-3.5 h-3.5" /></button></div></div></div>
    <div v-if="selected" class="rounded-xl border border-indigo-500/30 bg-slate-950/40 p-4 space-y-3"><div class="grid grid-cols-2 gap-3"><label class="text-xs text-slate-400">Name<input v-model="selected.name" class="field" /></label><label class="text-xs text-slate-400">Type<select v-model="selected.type" class="field" @change="updateType"><option value="shell">Shell command</option><option value="mcp">MCP (stdio)</option><option value="rest">REST API</option></select></label></div><label class="text-xs text-slate-400">Description<input v-model="selected.description" class="field" /></label><label v-if="selected.type === 'shell' || selected.type === 'mcp'" class="text-xs text-slate-400">Command<input v-model="selected.config.command" class="field font-mono" placeholder="php artisan route:list" /></label><label v-if="selected.type === 'rest'" class="text-xs text-slate-400">Method<select v-model="selected.config.method" class="field"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select></label><label v-if="selected.type === 'rest'" class="text-xs text-slate-400">URL template<input v-model="selected.config.url" class="field font-mono" placeholder="https://api.example.com/items/{{id}}" /></label><label v-if="selected.type === 'rest'" class="text-xs text-slate-400">Allowed hosts<input v-model="selected.config.allowedHosts" class="field" placeholder="api.example.com" /></label><label v-if="selected.type === 'rest'" class="text-xs text-slate-400">JSON body<textarea v-model="bodyText" rows="4" class="field font-mono" /></label><div class="mt-4 flex gap-2"><button class="px-3 py-2 rounded-lg bg-indigo-600 text-white text-xs" @click="save"><Save class="w-3.5 h-3.5 inline mr-1" />Save</button><button v-if="selected.id" class="px-3 py-2 rounded-lg border border-slate-700 text-xs text-slate-300" :disabled="testing" @click="test">{{ testing ? 'Testing…' : 'Test tool' }}</button><button class="px-3 py-2 rounded-lg border border-slate-700 text-xs text-slate-400" @click="selected=null">Cancel</button></div></div>
  </section>
</template>

<style scoped>.field{display:block;width:100%;margin-top:.35rem;border-radius:.6rem;border:1px solid rgb(51 65 85);background:#0f172a;color:#e2e8f0;padding:.55rem .7rem;font-size:.75rem}.field:focus{outline:2px solid rgb(99 102 241 / .45)}</style>
